:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

"use client";

import { useState, type ComponentPropsWithoutRef } from "react";
import "../foundation.css";

export interface AvatarProps extends Omit<ComponentPropsWithoutRef<"span">, "children"> {
  name: string;
  src?: string;
  size?: number;
}

export function Avatar({ name, src, size = 46, className, ...props }: AvatarProps) {
  const [failedSrc, setFailedSrc] = useState<string>();
  const initials = name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]).join("").toUpperCase();
  return (
    <span {...props} aria-label={props["aria-label"] ?? name} className={["relative inline-grid shrink-0 place-items-center overflow-hidden rounded-full bg-[var(--surface-muted)] text-[var(--text)] font-[650]", className].filter(Boolean).join(" ")} style={{ width: size, height: size, fontSize: size * .34, ...props.style }}>
      {src && failedSrc !== src ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={src} alt="" className="size-full object-cover" onError={() => setFailedSrc(src)} />
      ) : initials || "?"}
    </span>
  );
}

export interface AvatarGroupProps extends ComponentPropsWithoutRef<"div"> {
  items: readonly AvatarProps[];
  max?: number;
  size?: number;
}

export function AvatarGroup({ items, max = 4, size = 46, className, ...props }: AvatarGroupProps) {
  const visible = items.slice(0, Math.max(0, max));
  const remaining = items.length - visible.length;
  return (
    <div {...props} className={["inline-flex items-center", className].filter(Boolean).join(" ")}>
      {visible.map((item, index) => <Avatar {...item} size={size} key={`${item.name}-${index}`} className={["ring-2 ring-[var(--surface)]", index ? "-ml-3" : "", item.className].filter(Boolean).join(" ")} />)}
      {remaining > 0 ? <span aria-label={`${remaining} more people`} className="-ml-3 inline-grid shrink-0 place-items-center rounded-full bg-[var(--surface-muted)] text-xs font-[650] text-[var(--text)] ring-2 ring-[var(--surface)]" style={{ width: size, height: size }}>+{remaining}</span> : null}
    </div>
  );
}
